INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9767, 'koKR', 'Poznaj swojego wroga', 'Do pokonania wroga nie wystarczy przewaga sił czy liczebności. Zwycięstwo często zależy od znajomości słabości przeciwnika, przewidywania jego planów albo rozpoznania wzorców jego zachowania.$B$BWiemy wiele o nagach, lecz znaczna część ich praktyk magicznych wciąż pozostaje dla nas obca.$B$BChcę zgłębić hydromancję, którą posługują się nagi ze Zbiornika Żmijokolców. Przynieś mi jedną z ich ksiąg zaklęć, a dowiem się o niej więcej.', 'Zdobądź Księgę zaklęć Żmijokolców od nag w Zbiorniku Żmijokolców i zanieś ją Ashyen w Schronieniu Cenariona na Moczarach Zangarskich.', '', 'Wróć do Ashyen na Moczarach Zangarskich.', '', '', '', '', 0),
(9768, 'koKR', 'Księgi zaklęć Żmijokolców', '', '', '', 'Wróć do Ashyen na Moczarach Zangarskich.', '', '', '', '', 0);
