INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(18878, 'koKR', 'Musimy pracować szybciej.', '', 0),
(18879, 'koKR', 'Nasza praca jeszcze nie jest skończona.', '', 0),
(18880, 'koKR', 'Powinniście czuć się zaszczyceni, że wykonujecie polecenia Lady Vash.', '', 0),
(18881, 'koKR', 'Lady Vash oczekuje, że wkrótce skończymy pracę.', '', 0),
(18882, 'koKR', 'Skupcie się.', '', 0),
(18883, 'koKR', 'Utrzymujcie stałą pracę pomp.', '', 0),
(18884, 'koKR', 'Pompy mają pracować bez przerwy.', '', 0),
(18885, 'koKR', 'Jesteśmy już na ostatniej prostej.', '', 0),
(18886, 'koKR', 'Wszystko idzie zgodnie z planem.', '', 0),
(18887, 'koKR', 'Pompy działają wspaniale.', '', 0),
(18888, 'koKR', 'Wkrótce cała woda Draenoru będzie nasza.', '', 0),
(18889, 'koKR', 'Zbiornik ładnie się napełnia.', '', 0),
(18890, 'koKR', 'Oczyszczanie wody wyprzedza chyba harmonogram.', '', 0),
(18891, 'koKR', 'Wygląda na to, że trzymamy się planu.', '', 0),
(18892, 'koKR', 'Jeśli utrzymamy to tempo, Pani będzie zadowolona.', '', 0),
(18893, 'koKR', 'Niedługo osiągniemy pełną pojemność.', '', 0),
(18894, 'koKR', 'Pilnujcie, żeby wszyscy pracowali wydajnie.', '', 0),
(18895, 'koKR', 'Nie pozwólcie, żeby poziom za bardzo spadł.', '', 0),
(18896, 'koKR', 'Utrzymujcie wysokie ciśnienie na południowej pompie.', '', 0),
(18897, 'koKR', 'Skierujcie przepływ z zachodniego bagna.', '', 0),
(18898, 'koKR', 'Otwórzcie zawory oczyszczające i pracujcie dalej.', '', 0),
(18899, 'koKR', 'Dopilnujcie, żeby ci Złamani zostali porządnie umyci, zanim dotkną wody.', '', 0),
(18900, 'koKR', 'Regulujcie główny zawór, żeby przepływ był równy.', '', 0),
(18901, 'koKR', 'Nie spuszczajcie oka z tych plugawych Złamanych. Nie ufam im.', '', 0),
(18903, 'koKR', 'Całkowicie się zgadzam.', 'Całkowicie się zgadzam.', 0),
(18904, 'koKR', 'Jakbyś czytał w moich myślach.', 'Jakbyś czytał w moich myślach.', 0),
(18905, 'koKR', 'Mówisz prawdę.', 'Mówisz prawdę.', 0),
(18906, 'koKR', 'Tak jest.', 'Tak jest.', 0),
(18908, 'koKR', 'Dopilnuję tego, panie.', 'Dopilnuję tego, panie.', 0),
(18909, 'koKR', 'Co cię trapi, panie?', 'Co cię trapi, panie?', 0),
(18910, 'koKR', 'Wy plugawe istotki, macie pracować szybciej!', '', 0),
(18911, 'koKR', 'SZYBCIEJ!!!!', '', 0),
(19501, 'koKR', 'Nie... nie! Coście zrobili? To ja jestem panem! Słyszysz mnie? Ja jestem... aaach! Nie mogę... go powstrzymać.', '', 0),
(19502, 'koKR', 'Wreszcie jestem wolny. Zbyt długo nie kosztowałem prawdziwej wolności!', '', 0),
(19595, 'koKR', 'Precz, nędzny elfie. Teraz ja tu rządzę!', '', 0),
(19596, 'koKR', 'Wreszcie moje wygnanie dobiegło końca!', '', 0),
(19597, 'koKR', 'Każdy ma swoje demony...', '', 0),
(19606, 'koKR', 'Aaach, ta trucizna...', '', 0),
(19607, 'koKR', 'Lepiej, znacznie lepiej.', '', 0),
(19643, 'koKR', 'Śmiało, zabijcie ich! Tylko na tym zyskam!', '', 0),
(19644, 'koKR', 'Więcej wiedzy, więcej mocy!', '', 0),
(19645, 'koKR', 'Jestem potężniejszy niż kiedykolwiek!', '', 0),
(19679, 'koKR', '', 'Nie chciałam zniżać się do walki z waszym rodzajem, ale nie zostawiacie mi wyboru...', 0),
(19854, 'koKR', 'Wasza zbytnia pewność siebie was zgubi! Straże, użyczcie mi swej siły!', '', 0),
(19993, 'koKR', 'Nie mam sobie równych!', '', 0),
(19994, 'koKR', 'Giń, $gśmiertelniku:śmiertelniczko;!', '', 0),
(19995, 'koKR', 'Tak... tak!', '', 0),
(19996, 'koKR', 'Zabijać, zabijać!', '', 0),
(19997, 'koKR', 'Właśnie tak, tak!', '', 0),
(19998, 'koKR', 'Kto teraz jest panem?', '', 0),
(19999, 'koKR', 'Nie zdołacie mnie zabić, głupcy! Wrócę, ja...', '', 0),
(20000, 'koKR', 'Straże, baczność! Mamy gości...', '', 0),
(20001, 'koKR', 'Lądowe ścierwo!', '', 0),
(20002, 'koKR', 'Alana be\'lendor!', '', 0),
(20003, 'koKR', 'Pozbyłem się ciebie.', '', 0),
(20004, 'koKR', 'Jej... ekscelencja... czeka.', '', 0),
(20085, 'koKR', '', 'Woda... to życie. Stała się tu, na Rubieży, rzadkim dobrem – dobrem, nad którym tylko my będziemy panować. Jesteśmy Wysoko Urodzonymi i nadszedł wreszcie czas, byśmy odzyskali należne nam miejsce w świecie!', 0),
(20086, 'koKR', '', 'Prosto w serce!', 0),
(20087, 'koKR', '', 'Trafcie w cel!', 0),
(20088, 'koKR', '', 'Rozpłatam cię od dzioba po rufę!', 0),
(20089, 'koKR', '', 'Zwycięstwo dla lorda Illidana!', 0),
(20090, 'koKR', '', 'Śmierć obcym!', 0),
(20091, 'koKR', '', 'Pluję na ciebie, plugastwo z powierzchni!', 0),
(20092, 'koKR', '', 'Nadszedł czas! Nie zostawcie nikogo przy życiu!', 0),
(20094, 'koKR', '', '$GPoniosłeś:Poniosłaś; porażkę!', 0),
(20095, 'koKR', '', 'Be\'lemer an-delei!', 0),
(20096, 'koKR', '', 'Lordzie Illidanie, ja... ja... przepraszam.', 0),
(20210, 'koKR', '', 'Radzę wam się ukryć.', 0),
(20231, 'koKR', 'Nie pozwolę wam się wtrącać!', '', 0),
(20233, 'koKR', 'Wyplenię was z tego miejsca!', '', 0),
(20234, 'koKR', 'Nie jesteście lepsi od nich!', '', 0),
(20235, 'koKR', 'Zmusili mnie do tego...', '', 0),
(20236, 'koKR', 'Nie było innego wyjścia.', '', 0),
(20238, 'koKR', 'Nareszcie... wolność.', '', 0),
(20239, 'koKR', 'To wy... jesteście chorobą... nie ja...', '', 0),
(20700, 'koKR', 'Gwałtowne trzęsienie ziemi zaalarmowało pobliskie murloki!', '', 0),
(20701, 'koKR', '%s posyła swoich wrogów do wodnych grobów!', '', 0),
(20703, 'koKR', '%s przyzywa wodne kule!', '', 0),
(20931, 'koKR', 'Niech cię porwie powódź głębin!', '', 0),
(20933, 'koKR', 'Na pływy!', '', 0),
(20934, 'koKR', 'Zniszczcie ich, moi poddani!', '', 0),
(20935, 'koKR', 'Nie ma gdzie się ukryć!', '', 0),
(20936, 'koKR', 'Wkrótce to się skończy!', '', 0),
(20937, 'koKR', 'Stało się!', '', 0),
(20938, 'koKR', 'Szamotanie tylko pogarsza sprawę.', '', 0),
(20939, 'koKR', 'Przetrwają tylko silni.', '', 0),
(20940, 'koKR', 'Wielkie prądy... Ageona...', '', 0),
(49785, 'koKR', '', 'Twój czas właśnie się kończy!', 0);
